    `);

    // CRITICAL: Never return 0!
    if (positionSize === 0 || isNaN(positionSize)) {
      console.log('âš ï¸ Kelly returned 0, using minimum position');
      const minPosition = balance * this.config.minPositionSize / price;
      return {
        size: minPosition,
