      },
      'CRASH': {
        boost: ['emergency', 'recovery', 'hedge'],
        suppress: ['all_except_risk']
      }
    };

    const config = regimeConfig[newRegime];
    if (!config) return;

    // Boost certain component types
    config.boost?.forEach(type => {
      this.neurons.forEach(neuron => {
        if (neuron.type === type) {
          neuron.priority *= 1.5;
          this.boostNeuronConnections(neuron.id, 0.2);
        }
      });
    });

    // Suppress others
    config.suppress?.forEach(type => {
      this.neurons.forEach(neuron => {
        if (neuron.type === type || type === 'all_except_risk') {
          if (type === 'all_except_risk' && neuron.type === 'risk') return;

          neuron.priority *= 0.5;
          this.adjustConnectionWeights(neuron.id, -0.2);
        }
      });
    });

    this.emit('regime_adapted', {
      regime: newRegime,
      timestamp: Date.now(),
      activeNeurons: this.getActiveNeuronCount()
    });
  }

  /**
   * BOOST NEURON CONNECTIONS
   */
  boostNeuronConnections(neuronId, boost) {
    this.synapses.forEach(synapse => {
      if (synapse.from === neuronId) {
        synapse.weight = Math.min(1.0, synapse.weight + boost);
        if (synapse.state === 'dormant' && synapse.weight > 0.2) {
          synapse.state = 'active';
        }
      }
    });
  }

  /**
   * CORTEX DECISION AGGREGATION
   * Multiple neurons vote on decisions
   */
  async cortexDecision(decisionType, context) {
    const voters = [];

    // Find all neurons that can vote on this decision type
    this.neurons.forEach(neuron => {
      if (neuron.component?.canVote && neuron.component.canVote(decisionType)) {
        voters.push(neuron);
      }
    });

    if (voters.length === 0) {
      console.warn(`âš ï¸ No voters for decision type: ${decisionType}`);
      return null;
    }

    // Collect votes weighted by neuron performance
    const votes = await Promise.all(voters.map(async neuron => {
      try {
        const vote = await neuron.component.vote(decisionType, context);
        return {
          neuronId: neuron.id,
          vote,
          weight: neuron.performance.successRate * neuron.priority
        };
      } catch (error) {
        console.error(`Vote error from ${neuron.id}:`, error.message);
        return null;
      }
    }));

    // Aggregate votes
    const validVotes = votes.filter(v => v !== null);
    if (validVotes.length === 0) return null;

    const aggregated = this.aggregateVotes(validVotes);

    return {
      decision: aggregated.decision,
      confidence: aggregated.confidence,
      voters: validVotes.length,
      timestamp: Date.now()
    };
  }

  /**
   * AGGREGATE VOTES WITH WEIGHTED CONSENSUS
   */
  aggregateVotes(votes) {
    const voteMap = new Map();
    let totalWeight = 0;

    votes.forEach(({ vote, weight }) => {
      const current = voteMap.get(vote) || 0;
      voteMap.set(vote, current + weight);
      totalWeight += weight;
    });

    // Find decision with highest weight
    let maxWeight = 0;
    let decision = null;

    voteMap.forEach((weight, vote) => {
      if (weight > maxWeight) {
        maxWeight = weight;
        decision = vote;
      }
    });

    return {
      decision,
      confidence: maxWeight / totalWeight
    };
  }

  /**
   * PERFORMANCE TRACKING
   */
  trackPerformance(neuron) {
    // Track success rate
    neuron.component.on?.('success', (data) => {
      this.updateNeuronPerformance(neuron.id, {
        success: true,
        profit: data.profit || 0
      });
    });

    neuron.component.on?.('failure', (data) => {
      this.updateNeuronPerformance(neuron.id, {
        success: false,
        loss: data.loss || 0
      });
    });
  }

  /**
   * UPDATE NEURON PERFORMANCE
   */
  updateNeuronPerformance(neuronId, metrics) {
    const neuron = this.neurons.get(neuronId);
    if (!neuron) return;

    const perf = neuron.performance;

    // Update success rate (exponential moving average)
    if (metrics.success !== undefined) {
      perf.successRate = perf.successRate * 0.95 + (metrics.success ? 1 : 0) * 0.05;
    }

    // Update latency
    if (metrics.latency !== undefined) {
      perf.avgLatency = perf.avgLatency * 0.9 + metrics.latency * 0.1;
    }

    // Update profit contribution
    if (metrics.profit !== undefined) {
      perf.profitContribution += metrics.profit;
    }
    if (metrics.loss !== undefined) {
      perf.profitContribution -= metrics.loss;
    }

    // Adjust neuron priority based on performance
    if (perf.successRate > 0.7 && perf.profitContribution > 0) {
      neuron.priority = Math.min(10, neuron.priority * 1.01);
    } else if (perf.successRate < 0.3) {
      neuron.priority = Math.max(0.1, neuron.priority * 0.99);
    }
  }

  /**
   * HEALTH MONITORING
   */
  monitorHealth() {
    setInterval(() => {
      this.neurons.forEach((neuron, id) => {
        const lastHeartbeat = this.healthMonitor.heartbeats.get(id) || 0;
        const timeSinceHeartbeat = Date.now() - lastHeartbeat;

        if (timeSinceHeartbeat > 60000) {  // 1 minute without heartbeat
          console.warn(`âš ï¸ Neuron ${id} may be unresponsive`);
          neuron.state = 'unresponsive';

          // Reduce connections to unresponsive neurons
          this.adjustConnectionWeights(id, -0.3);
        }
      });

      // Attempt recovery of failed neurons
      this.attemptRecovery();

    }, 30000);  // Every 30 seconds
  }

  /**
   * ATTEMPT RECOVERY OF FAILED COMPONENTS
   */
  attemptRecovery() {
    this.neurons.forEach((neuron, id) => {
      if (neuron.state === 'unresponsive' || neuron.state === 'failed') {
        const failures = this.healthMonitor.failures.get(id) || 0;

        if (failures < 3) {  // Max 3 recovery attempts
          console.log(`ðŸ”§ Attempting recovery of ${id}`);

          // Try to reinitialize component
          if (neuron.component?.reinitialize) {
            neuron.component.reinitialize()
              .then(() => {
                neuron.state = 'active';
                console.log(`âœ… ${id} recovered successfully`);

                // Gradually restore connections
                this.adjustConnectionWeights(id, 0.1);
              })
              .catch(error => {
                console.error(`âŒ ${id} recovery failed:`, error.message);
                this.healthMonitor.failures.set(id, failures + 1);
              });
          }
        }
      }
    });
  }

  /**
   * GET MESH STATUS
   */
  getMeshStatus() {
    const activeNeurons = Array.from(this.neurons.values())
      .filter(n => n.state === 'active').length;

    const activeSynapses = Array.from(this.synapses.values())
      .filter(s => s.state === 'active').length;

    const avgSuccessRate = Array.from(this.neurons.values())
      .reduce((sum, n) => sum + n.performance.successRate, 0) / this.neurons.size;

    const totalProfit = Array.from(this.neurons.values())
      .reduce((sum, n) => sum + n.performance.profitContribution, 0);

    return {
      neurons: {
        total: this.neurons.size,
        active: activeNeurons,
        performance: avgSuccessRate
      },
      synapses: {
        total: this.synapses.size,
        active: activeSynapses
      },
      regime: this.currentRegime,
      totalProfit,
      uptime: Date.now() - (this.startTime || Date.now())
    };
  }

  /**
   * EMERGENCY SHUTDOWN
   */
  emergencyShutdown(reason) {
    console.log(`ðŸš¨ EMERGENCY SHUTDOWN: ${reason}`);

    // Deactivate all synapses
    this.synapses.forEach(synapse => {
      synapse.state = 'emergency_stop';
    });

    // Put all neurons in safe mode
    this.neurons.forEach(neuron => {
      if (neuron.component?.safeMode) {
        neuron.component.safeMode();
      }
      neuron.state = 'safe_mode';
    });

    this.emit('emergency_shutdown', {
      reason,
      timestamp: Date.now(),
      status: this.getMeshStatus()
    });
  }

  /**
   * GET ACTIVE NEURON COUNT
   */
  getActiveNeuronCount() {
    return Array.from(this.neurons.values())
      .filter(n => n.state === 'active').length;
  }
}

