    }

    // ====================================================================
    // MONTHLY PERFORMANCE BREAKDOWN
    // ====================================================================

    console.log(`\nMONTHLY PERFORMANCE:`);
    const monthlyEntries = Object.entries(this.data.monthlyReturns);
    if (monthlyEntries.length > 0) {
