  invalidateRelatedCache(timeframe) {
    let invalidated = 0;

    for (const key of this.candleCache.keys()) {
      if (key.includes(timeframe)) {
        this.candleCache.delete(key);
        this.cacheTimestamps.delete(key);
        invalidated++;
      }
