    startTrading() {
        console.log('ðŸš€ Starting trading loop...');
        // Send status every 5 seconds
        setInterval(() => {
            console.log(`â° Trade check - connected: ${this.connected}, ws state: ${this.ws ? this.ws.readyState : 'no ws'}`);
            if (!this.connected) {
