          { name: 'refreshToken', label: 'Refresh Token', type: 'password', required: false },
          { name: 'accessToken', label: 'Access Token', type: 'password', required: false },
          { name: 'redirectUri', label: 'Redirect URI', type: 'text', required: false }
        ]
      },
    ];
  }

  /**
   * Add a new broker configuration
   * @param {string} userId - User identifier
   * @param {string} brokerId - Broker identifier
   * @param {string} configName - Configuration name
   * @param {Object} credentials - Broker credentials
   * @param {Object} settings - Additional settings
   * @returns {Promise<string>} Configuration ID
   */
  async addBrokerConfig(userId, brokerId, configName, credentials, settings = {}) {
    try {
      // Validate broker ID
      if (!this.config.supportedBrokers.includes(brokerId)) {
        throw new Error(`Unsupported broker: ${brokerId}`);
      }

      // Validate required fields
      const brokerInfo = this.getSupportedBrokers().find(b => b.id === brokerId);
      const missingFields = brokerInfo.requiredFields
        .filter(field => field.required && !credentials[field.name])
        .map(field => field.label);

      if (missingFields.length > 0) {
        throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
      }

      // Check configuration limit
      const userConfigs = this.getUserConfigurations(userId);
      if (userConfigs.length >= this.config.maxConfigs) {
        throw new Error(`Maximum number of configurations (${this.config.maxConfigs}) reached`);
      }

      // Create configuration
      const configId = this.generateConfigId();
      const configuration = {
        id: configId,
        userId,
        brokerId,
        name: configName,
        credentials: this.encryptCredentials(credentials),
        settings,
        createdAt: new Date().toISOString(),
        lastUsed: null,
        active: true
      };

      // Test connection before saving
      await this.testBrokerConnection(brokerId, credentials);

      // Store configuration
      this.configurations.set(configId, configuration);

      // Save to disk
      this.saveConfiguration(configId, configuration);

      console.log(`âœ… Added broker configuration: ${configName} (${brokerId})`);

      return configId;
    } catch (error) {
      console.error(`âŒ Failed to add broker configuration: ${error.message}`);
      throw error;
    }
  }

  /**
   * Update an existing broker configuration
   * @param {string} configId - Configuration ID
   * @param {Object} updates - Updates to apply
   * @returns {Promise<boolean>} Success status
   */
  async updateBrokerConfig(configId, updates) {
    try {
      const config = this.configurations.get(configId);
      if (!config) {
        throw new Error('Configuration not found');
      }

      // Create updated configuration
      const updatedConfig = {
        ...config,
        ...updates,
        updatedAt: new Date().toISOString()
      };

      // If credentials are being updated, test connection
      if (updates.credentials) {
        updatedConfig.credentials = this.encryptCredentials(updates.credentials);
        await this.testBrokerConnection(config.brokerId, updates.credentials);
      }

      // Update in memory and save to disk
      this.configurations.set(configId, updatedConfig);
      this.saveConfiguration(configId, updatedConfig);

      console.log(`âœ… Updated broker configuration: ${configId}`);

      return true;
    } catch (error) {
      console.error(`âŒ Failed to update broker configuration: ${error.message}`);
      throw error;
    }
  }

  /**
   * Remove a broker configuration
   * @param {string} configId - Configuration ID
   * @returns {boolean} Success status
   */
  removeBrokerConfig(configId) {
    try {
      const config = this.configurations.get(configId);
      if (!config) {
        throw new Error('Configuration not found');
      }

      // Remove from memory
      this.configurations.delete(configId);

      // Remove file
      const configFile = path.join(this.config.configDirectory, `${configId}.json`);
      if (fs.existsSync(configFile)) {
        fs.unlinkSync(configFile);
      }

      console.log(`âœ… Removed broker configuration: ${configId}`);

      return true;
    } catch (error) {
      console.error(`âŒ Failed to remove broker configuration: ${error.message}`);
      throw error;
    }
  }

  /**
   * Get broker configuration by ID
   * @param {string} configId - Configuration ID
   * @returns {Object|null} Configuration or null if not found
   */
  getBrokerConfig(configId) {
    const config = this.configurations.get(configId);
    if (!config) return null;

    // Return decrypted configuration
    return {
      ...config,
      credentials: this.decryptCredentials(config.credentials)
    };
  }

  /**
   * Get all configurations for a user
   * @param {string} userId - User identifier
   * @returns {Array} Array of user configurations
   */
  getUserConfigurations(userId) {
    const userConfigs = [];

    for (const [configId, config] of this.configurations) {
      if (config.userId === userId && config.active) {
        userConfigs.push({
          ...config,
          credentials: this.decryptCredentials(config.credentials)
        });
      }
    }

    return userConfigs.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }

  /**
   * Test broker connection
   * @param {string} brokerId - Broker identifier
   * @param {Object} credentials - Broker credentials
   * @returns {Promise<boolean>} Connection test result
   */
  async testBrokerConnection(brokerId, credentials) {
    try {
      // Create temporary adapter for testing
      const AdapterClass = this.getBrokerAdapterClass(brokerId);
      const testAdapter = new AdapterClass(credentials);

      // Test connection
      const connected = await testAdapter.connect();

      // Clean up
      await testAdapter.disconnect();

      return connected;
    } catch (error) {
      throw new Error(`Connection test failed: ${error.message}`);
    }
  }

  /**
   * Get broker adapter class
   * @param {string} brokerId - Broker identifier
   * @returns {Class} Adapter class
   * @private
   */
  getBrokerAdapterClass(brokerId) {
    const adapterMap = {
      'alpaca': require('./adapters/AlpacaAdapter'),
      'robinhood': require('./adapters/RobinhoodAdapter'),
      'tdameritrade': require('./adapters/TDAmeriteAdapter'),
      'kraken': require('./adapters/KrakenAdapter'),
      'coinbase': require('./adapters/CoinbaseAdapter'),
      'binance': require('./adapters/BinanceAdapter'),
      'ibkr': require('./adapters/IBKRAdapter')
    };

    const AdapterClass = adapterMap[brokerId];
    if (!AdapterClass) {
      throw new Error(`Adapter not found for broker: ${brokerId}`);
    }

    return AdapterClass;
  }

  /**
   * Load all configurations from disk
   * @private
   */
  loadConfigurations() {
    try {
      const configFiles = fs.readdirSync(this.config.configDirectory)
        .filter(file => file.endsWith('.json'));

      for (const file of configFiles) {
        const configPath = path.join(this.config.configDirectory, file);
        const configData = JSON.parse(fs.readFileSync(configPath, 'utf8'));

        this.configurations.set(configData.id, configData);
      }

      console.log(`ðŸ“‹ Loaded ${this.configurations.size} broker configurations`);
    } catch (error) {
      console.error('âŒ Failed to load configurations:', error.message);
    }
  }

  /**
   * Save configuration to disk
   * @param {string} configId - Configuration ID
   * @param {Object} configuration - Configuration data
   * @private
   */
  saveConfiguration(configId, configuration) {
    const configFile = path.join(this.config.configDirectory, `${configId}.json`);
    fs.writeFileSync(configFile, JSON.stringify(configuration, null, 2));
  }

  /**
   * Encrypt credentials
   * @param {Object} credentials - Credentials to encrypt
   * @returns {Object} Encrypted credentials
   * @private
   */
  encryptCredentials(credentials) {
    const algorithm = 'aes-256-gcm';
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipher(algorithm, this.config.encryptionKey);

    let encrypted = cipher.update(JSON.stringify(credentials), 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return {
      encrypted,
      iv: iv.toString('hex'),
      authTag: authTag.toString('hex')
    };
  }

  /**
   * Decrypt credentials
   * @param {Object} encryptedData - Encrypted credentials
   * @returns {Object} Decrypted credentials
   * @private
   */
  decryptCredentials(encryptedData) {
    try {
      const algorithm = 'aes-256-gcm';
      const decipher = crypto.createDecipher(algorithm, this.config.encryptionKey);

      decipher.setAuthTag(Buffer.from(encryptedData.authTag, 'hex'));

      let decrypted = decipher.update(encryptedData.encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      return JSON.parse(decrypted);
    } catch (error) {
      console.error('âŒ Failed to decrypt credentials:', error.message);
      return {};
    }
  }

  /**
   * Generate encryption key
   * @returns {string} Encryption key
   * @private
   */
  generateEncryptionKey() {
    return crypto.randomBytes(32).toString('hex');
  }

  /**
   * Generate configuration ID
   * @returns {string} Configuration ID
   * @private
   */
  generateConfigId() {
    return `config_${Date.now()}_${crypto.randomBytes(8).toString('hex')}`;
  }

  /**
   * Export configurations for backup
   * @param {string} userId - User identifier
   * @returns {Object} Exported configurations
   */
  exportConfigurations(userId) {
    const userConfigs = this.getUserConfigurations(userId);

    return {
      exportedAt: new Date().toISOString(),
      configurations: userConfigs.map(config => ({
        ...config,
        credentials: this.encryptCredentials(config.credentials) // Re-encrypt for export
      }))
    };
  }

  /**
   * Import configurations from backup
   * @param {string} userId - User identifier
   * @param {Object} exportedData - Exported configuration data
   * @returns {number} Number of configurations imported
   */
  importConfigurations(userId, exportedData) {
    let importedCount = 0;

    for (const config of exportedData.configurations) {
      try {
        // Generate new ID for imported config
        const newConfigId = this.generateConfigId();
        const importedConfig = {
          ...config,
          id: newConfigId,
          userId,
          importedAt: new Date().toISOString()
        };

        // Store configuration
        this.configurations.set(newConfigId, importedConfig);
        this.saveConfiguration(newConfigId, importedConfig);

        importedCount++;
      } catch (error) {
        console.error(`âŒ Failed to import configuration: ${error.message}`);
      }
    }

    console.log(`âœ… Imported ${importedCount} broker configurations`);

    return importedCount;
  }

  /**
   * Update last used timestamp
   * @param {string} configId - Configuration ID
   */
  markConfigUsed(configId) {
    const config = this.configurations.get(configId);
    if (config) {
      config.lastUsed = new Date().toISOString();
      this.saveConfiguration(configId, config);
    }
  }

  /**
   * Get configuration summary
   * @returns {Object} Summary statistics
   */
  getSummary() {
    const totalConfigs = this.configurations.size;
    const brokerCounts = {};

    for (const config of this.configurations.values()) {
      brokerCounts[config.brokerId] = (brokerCounts[config.brokerId] || 0) + 1;
    }

    return {
      totalConfigurations: totalConfigs,
      brokerBreakdown: brokerCounts,
      supportedBrokers: this.config.supportedBrokers
    };
  }
}

module.exports = BrokerConfigManager;

// CoinbaseAdapter.js - Coinbase Pro broker adapter
// Handles cryptocurrency trading through Coinbase Pro API

const BaseBrokerAdapter = require('./BaseBrokerAdapter');
const crypto = require('crypto');
const axios = require('axios');

/**
 * Coinbase Pro Broker Adapter
 * Supports cryptocurrency trading with advanced order types
 */
class CoinbaseAdapter extends BaseBrokerAdapter {
  constructor(config = {}) {
    super({
      name: 'coinbase',
      baseUrl: config.sandbox ? 'https://api-public.sandbox.pro.coinbase.com' : 'https://api.pro.coinbase.com',
      maxRequestsPerSecond: 10, // Coinbase Pro rate limits
      ...config
    });

    // Coinbase-specific capabilities
    this.capabilities = {
      markets: ['crypto'],
      orderTypes: ['market', 'limit', 'stop'],
      timeInForce: ['GTC', 'IOC', 'FOK', 'GTT'],
      streaming: true,
      paperTrading: true, // Sandbox mode
      fractionalShares: true,
      crypto: true,
      options: false,
      forex: false
    };

    // API client
    this.client = null;

    // Coinbase-specific state
    this.products = new Map();
  }

  /**
   * Connect to Coinbase Pro
   * @returns {Promise<boolean>} Connection success
   */
  async connect() {
    try {
      this.log('info', 'Connecting to Coinbase Pro...');

      // Validate credentials
      if (!this.config.apiKey || !this.config.apiSecret || !this.config.passphrase) {
        throw new Error('API key, secret, and passphrase are required');
      }

      // Setup HTTP client
      this.client = axios.create({
        baseURL: this.config.baseUrl,
        timeout: this.config.connectionTimeout
      });

      // Load available products
      await this.loadProducts();

      // Test private API access
      const accountsResponse = await this.makePrivateRequest('GET', '/accounts');

      this.setConnected(true);
      this.resetConnectionAttempts();

      this.log('info', 'Successfully connected to Coinbase Pro', {
        products: this.products.size,
        accounts: accountsResponse.length
      });

      return true;
    } catch (error) {
      this.log('error', 'Failed to connect to Coinbase Pro', { error: error.message });
      await this.handleConnectionError(error);
      return false;
    }
  }

  /**
   * Load available trading products
   * @private
   */
  async loadProducts() {
    try {
      const response = await this.client.get('/products');

      this.products.clear();
      for (const product of response.data) {
        if (product.status === 'online') {
          this.products.set(product.id, product);
        }
      }

      this.log('info', `Loaded ${this.products.size} trading products`);
    } catch (error) {
      this.log('error', 'Failed to load products', { error: error.message });
      throw error;
    }
  }

  /**
   * Disconnect from Coinbase Pro
   * @returns {Promise<boolean>} Disconnection success
   */
  async disconnect() {
    try {
      this.log('info', 'Disconnecting from Coinbase Pro...');

      // Clear client and state
      this.client = null;
      this.products.clear();

      this.setConnected(false);
      this.log('info', 'Disconnected from Coinbase Pro');

      return true;
    } catch (error) {
      this.log('error', 'Error disconnecting from Coinbase Pro', { error: error.message });
      return false;
    }
  }

  /**
   * Place an order on Coinbase Pro
   * @param {Object} order - Order parameters
   * @returns {Promise<Object>} Order result
   */
  async placeOrder(order) {
    try {
      // Validate order
      const validation = this.validateOrder(order);
      if (!validation.valid) {
        throw new Error(`Order validation failed: ${validation.errors.join(', ')}`);
      }

      // Check rate limit
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      // Convert symbol to Coinbase format
      const coinbaseSymbol = this.convertToCoinbaseSymbol(order.symbol);
      if (!coinbaseSymbol) {
        throw new Error(`Unsupported symbol: ${order.symbol}`);
      }

      // Prepare Coinbase order
      const coinbaseOrder = {
        product_id: coinbaseSymbol,
        side: order.side,
        type: order.type,
        size: order.quantity.toString()
      };

      // Add price for limit orders
      if (order.type === 'limit' && order.price) {
        coinbaseOrder.price = order.price.toString();
      }

      // Add client order ID if provided
      if (order.clientOrderId) {
        coinbaseOrder.client_oid = order.clientOrderId;
      }

      // Add time in force
      if (order.timeInForce && order.timeInForce !== 'GTC') {
        coinbaseOrder.time_in_force = order.timeInForce;
      }

      this.log('info', 'Placing order', { order: coinbaseOrder });

      // Submit order
      const response = await this.makePrivateRequest('POST', '/orders', coinbaseOrder);

      // Normalize response
      const normalizedOrder = this.normalizeCoinbaseOrder(response);

      // Store order
      this.orders.set(normalizedOrder.orderId, normalizedOrder);

      this.log('info', 'Order placed successfully', { 
        orderId: normalizedOrder.orderId,
        symbol: normalizedOrder.symbol,
        side: normalizedOrder.side,
        quantity: normalizedOrder.quantity
      });

      // Emit order placed event
      this.emit('orderPlaced', normalizedOrder);

      return normalizedOrder;
    } catch (error) {
      this.log('error', 'Failed to place order', { 
        error: error.response?.data?.message || error.message,
        order 
      });
      throw new Error(`Coinbase order failed: ${error.response?.data?.message || error.message}`);
    }
  }

  /**
   * Cancel an order
   * @param {string} orderId - Order ID to cancel
   * @returns {Promise<Object>} Cancellation result
   */
  async cancelOrder(orderId) {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      this.log('info', 'Cancelling order', { orderId });

      const response = await this.makePrivateRequest('DELETE', `/orders/${orderId}`);

      // Remove from local orders
      this.orders.delete(orderId);

      this.log('info', 'Order cancelled successfully', { orderId });

      this.emit('orderCancelled', { orderId });

      return {
        orderId,
        status: 'cancelled',
        timestamp: Date.now()
      };
    } catch (error) {
      this.log('error', 'Failed to cancel order', { 
        orderId,
        error: error.response?.data?.message || error.message 
      });
      throw new Error(`Failed to cancel order: ${error.response?.data?.message || error.message}`);
    }
  }

  /**
   * Get current positions (account balances)
   * @returns {Promise<Array>} Array of positions
   */
  async getPositions() {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('GET', '/accounts');

      const positions = [];

      for (const account of response) {
        const balance = parseFloat(account.balance);

        if (balance > 0) {
          positions.push(this.normalizePosition({
            symbol: account.currency,
            quantity: balance,
            side: 'long',
            avgPrice: 0, // Not available from accounts endpoint
            marketValue: balance, // For base currencies
            unrealizedPnL: 0,
            realizedPnL: 0,
            lastPrice: 0
          }));
        }
      }

      return positions;
    } catch (error) {
      this.log('error', 'Failed to get positions', { error: error.message });
      throw new Error(`Failed to get positions: ${error.message}`);
    }
  }

  /**
   * Get account balance
   * @returns {Promise<Object>} Account balance information
   */
  async getAccountBalance() {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('GET', '/accounts');

      // Find USD account
      const usdAccount = response.find(acc => acc.currency === 'USD' || acc.currency === 'USDC');
      const usdBalance = usdAccount ? parseFloat(usdAccount.balance) : 0;

      // Calculate total portfolio value (simplified)
      let totalValue = usdBalance;

      return this.normalizeBalance({
        cash: usdBalance,
        equity: totalValue,
        buyingPower: usdBalance,
        dayTradingBuyingPower: usdBalance,
        currency: 'USD'
      });
    } catch (error) {
      this.log('error', 'Failed to get account balance', { error: error.message });
      throw new Error(`Failed to get account balance: ${error.message}`);
    }
  }

  /**
   * Check if symbol is supported
   * @param {string} symbol - Trading symbol
   * @returns {boolean} Whether symbol is supported
   */
  supportsSymbol(symbol) {
    const coinbaseSymbol = this.convertToCoinbaseSymbol(symbol);
    return coinbaseSymbol !== null && this.products.has(coinbaseSymbol);
  }

  /**
   * Get order by ID
   * @param {string} orderId - Order ID
   * @returns {Promise<Object>} Order information
   */
  async getOrder(orderId) {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('GET', `/orders/${orderId}`);
      return this.normalizeCoinbaseOrder(response);
    } catch (error) {
      this.log('error', 'Failed to get order', { orderId, error: error.message });
      throw new Error(`Failed to get order: ${error.message}`);
    }
  }

  /**
   * Make authenticated request to Coinbase Pro
   * @param {string} method - HTTP method
   * @param {string} endpoint - API endpoint
   * @param {Object} body - Request body
   * @returns {Promise<Object>} API response
   * @private
   */
  async makePrivateRequest(method, endpoint, body = null) {
    const timestamp = Date.now() / 1000;
    const bodyString = body ? JSON.stringify(body) : '';

    // Create signature
    const message = timestamp + method + endpoint + bodyString;
    const signature = crypto
      .createHmac('sha256', Buffer.from(this.config.apiSecret, 'base64'))
      .update(message)
      .digest('base64');

    // Prepare request
    const requestConfig = {
      method: method.toLowerCase(),
      url: endpoint,
      headers: {
        'CB-ACCESS-KEY': this.config.apiKey,
        'CB-ACCESS-SIGN': signature,
        'CB-ACCESS-TIMESTAMP': timestamp,
        'CB-ACCESS-PASSPHRASE': this.config.passphrase,
        'Content-Type': 'application/json'
      }
    };

    if (body) {
      requestConfig.data = body;
    }

    // Make request
    const response = await this.client(requestConfig);
    return response.data;
  }

  /**
   * Convert symbol to Coinbase format
   * @param {string} symbol - Standard symbol (e.g., BTC-USD)
   * @returns {string|null} Coinbase symbol or null if not supported
   * @private
   */
  convertToCoinbaseSymbol(symbol) {
    // Coinbase Pro uses the same format as our standard (BTC-USD)
    // But we need to check if it exists in their products
    if (this.products.has(symbol)) {
      return symbol;
    }

    // Try some common variations
    const variations = [
      symbol,
      symbol.replace('-', ''),
      symbol.replace('/', '-'),
      symbol.toUpperCase()
    ];

    for (const variation of variations) {
      if (this.products.has(variation)) {
        return variation;
      }
    }

    return null;
  }

  /**
   * Normalize Coinbase order
   * @param {Object} coinbaseOrder - Coinbase order data
   * @returns {Object} Normalized order
   * @private
   */
  normalizeCoinbaseOrder(coinbaseOrder) {
    return {
      orderId: coinbaseOrder.id,
      clientOrderId: coinbaseOrder.client_oid || null,
      symbol: this.convertFromCoinbaseSymbol(coinbaseOrder.product_id),
      side: coinbaseOrder.side,
      quantity: parseFloat(coinbaseOrder.size || coinbaseOrder.specified_funds || 0),
      price: coinbaseOrder.price ? parseFloat(coinbaseOrder.price) : null,
      type: coinbaseOrder.type,
      status: this.normalizeCoinbaseOrderStatus(coinbaseOrder.status),
      fillPrice: coinbaseOrder.executed_value && coinbaseOrder.filled_size 
        ? parseFloat(coinbaseOrder.executed_value) / parseFloat(coinbaseOrder.filled_size) 
        : null,
      filledQuantity: parseFloat(coinbaseOrder.filled_size || 0),
      timestamp: new Date(coinbaseOrder.created_at).getTime(),
      fees: parseFloat(coinbaseOrder.fill_fees || 0)
    };
  }

  /**
   * Convert from Coinbase symbol format
   * @param {string} coinbaseSymbol - Coinbase symbol
   * @returns {string} Standard symbol
   * @private
   */
  convertFromCoinbaseSymbol(coinbaseSymbol) {
    // Coinbase Pro symbols are already in our standard format
    return coinbaseSymbol;
  }

  /**
   * Normalize Coinbase order status
   * @param {string} coinbaseStatus - Coinbase order status
   * @returns {string} Normalized status
   * @private
   */
  normalizeCoinbaseOrderStatus(coinbaseStatus) {
    const statusMap = {
      'pending': 'pending',
      'open': 'pending',
      'active': 'pending',
      'done': 'filled',
      'settled': 'filled',
      'cancelled': 'cancelled',
      'canceled': 'cancelled',
      'rejected': 'rejected'
    };

    return statusMap[coinbaseStatus] || 'unknown';
  }
}

