   */
  async sb2(Q, steps = 1000, dt = 0.01, gamma = 0.1, noise0 = 0.2) {
    return tf.tidy(() => {
      const n = Q.shape[0];

      // Initialize positions and momenta
      let x = tf.randomUniform([n], -1, 1);
      let p = tf.zeros([n]);

      // Time evolution
      for (let t = 0; t < steps; t++) {
