        if (data.articles) {
          articles.push(...data.articles.map(article => ({
            title: article.title,
            description: article.description,
            content: article.content,
            url: article.url,
            publishedAt: article.publishedAt,
            source: article.source.name
          })));
        }
      } catch (error) {
        console.error('NewsAPI error:', error);
      }
