                improvements: evolution.improvements
            }));
        });
    }

    executeBuy() {
        this.ws.send(JSON.stringify({
            type: 'trade',
            source: 'trading_bot',
            botTier: BOT_TIER,
            action: 'BUY',
            price: this.currentPrice || 100000, // Use real BTC price
