    if (data.metrics) {
      this.realtimeMetrics = { ...this.realtimeMetrics, ...data.metrics };
    }

    console.log('ðŸ§  Learning data imported successfully!');
  }

  /**
   * Stop learning system
   */
  stop() {
    this.processor.stop();
    console.log('ðŸ›‘ Learning System stopped');
