        break;
      case 'warning':
        prefix = 'âš ï¸';
        break;
      case 'info':
        prefix = 'ðŸ’°';
        break;
      case 'debug':
        prefix = 'ðŸ”';
        break;
    }

    const timestamp = new Date().toISOString();
    console.log(`${prefix} [${timestamp}] [MaxProfitManager] ${message}`);
  }
}


