  connectToArchon() {
    const wsUrl = `ws://${this.archonUrl.replace('http://', '')}/ws`;
    this.ws = new WebSocket(wsUrl);

    this.ws.on('open', () => {
      console.log('ðŸ“¡ Connected to Archon Knowledge Stream');
