 */

class PerformanceValidator {
  constructor(config = {}) {
    this.config = {
      // ðŸŽ¯ PROFITABILITY THRESHOLDS
      minProfitabilityThreshold: config.minProfitabilityThreshold || 0.55, // 55% win rate minimum
