      sbResult.solution,
      marketData.assets,
      capital
    );

    return {
      portfolio: optimalPortfolio,
      expectedReturn: this.calculateExpectedReturn(optimalPortfolio),
      risk: this.calculateRisk(optimalPortfolio),
      sharpeRatio: this.calculateSharpe(optimalPortfolio),
      quantumAdvantage: true
    };
  }

  // Utility functions
  calculateEnergy(solution, Q) {
    let energy = 0;
    for (let i = 0; i < solution.length; i++) {
      for (let j = 0; j < solution.length; j++) {
        energy += Q[i][j] * solution[i] * solution[j];
      }
    }
    return energy;
  }

  calculateIsingEnergy(spins, J, h) {
    let energy = 0;
    for (let i = 0; i < spins.length; i++) {
      energy -= h[i] * spins[i];
      for (let j = i + 1; j < spins.length; j++) {
        energy -= J[i][j] * spins[i] * spins[j];
      }
    }
    return energy;
  }

  quboToIsing(Q) {
    const n = Q.length;
    const J = Array(n).fill().map(() => Array(n).fill(0));
    const h = Array(n).fill(0);

    // Convert QUBO to Ising
    for (let i = 0; i < n; i++) {
      h[i] = Q[i][i] / 2;
      for (let j = 0; j < n; j++) {
        h[i] += Q[i][j] / 4;
        h[j] += Q[i][j] / 4;
      }
    }

    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        J[i][j] = Q[i][j] / 4;
        J[j][i] = J[i][j];
      }
    }

    return { J, h };
  }

  calculateCovariance(asset1, asset2) {
    // Historical covariance calculation
    const returns1 = asset1.historicalReturns || [];
    const returns2 = asset2.historicalReturns || [];

    if (returns1.length === 0 || returns2.length === 0) {
      return 0.01; // Default small covariance
    }

    const mean1 = returns1.reduce((a, b) => a + b) / returns1.length;
    const mean2 = returns2.reduce((a, b) => a + b) / returns2.length;

    let covariance = 0;
    for (let i = 0; i < returns1.length; i++) {
      covariance += (returns1[i] - mean1) * (returns2[i] - mean2);
    }

    return covariance / (returns1.length - 1);
  }

  addCardinalityConstraint(Q, maxPositions) {
    // Penalty for exceeding max positions
    const penalty = 100; // Large penalty weight
    const n = Q.length;

    // Add penalty term: penalty * (sum(q) - maxPositions)^2
    for (let i = 0; i < n; i++) {
      Q[i][i] += penalty * (1 - 2 * maxPositions);
      for (let j = i + 1; j < n; j++) {
        Q[i][j] += 2 * penalty;
        Q[j][i] = Q[i][j];
      }
    }
  }

  addSectorConstraints(Q, assets, sectorLimits) {
    // Penalty for exceeding sector limits
    const penalty = 50;

    for (const [sector, limit] of Object.entries(sectorLimits)) {
      const sectorIndices = assets
        .map((a, i) => a.sector === sector ? i : -1)
        .filter(i => i >= 0);

      // Add penalty for this sector
      for (const i of sectorIndices) {
        Q[i][i] += penalty * (1 - 2 * limit);
        for (const j of sectorIndices) {
          if (i !== j) {
            Q[i][j] += penalty;
            Q[j][i] = Q[i][j];
          }
        }
      }
    }
  }

  extractPortfolio(solution, assets, capital) {
    const portfolio = [];
    let totalAllocated = 0;

    for (let i = 0; i < solution.length; i++) {
      if (solution[i] === 1) {
        const allocation = capital / solution.reduce((a, b) => a + b, 0);
        portfolio.push({
          asset: assets[i],
          allocation: allocation,
          shares: Math.floor(allocation / assets[i].price)
        });
        totalAllocated += allocation;
      }
    }

    return portfolio;
  }

  calculateExpectedReturn(portfolio) {
    return portfolio.reduce((total, position) => {
      return total + position.allocation * position.asset.expectedReturn;
    }, 0);
  }

  calculateRisk(portfolio) {
    // Portfolio variance calculation
    let variance = 0;

    for (let i = 0; i < portfolio.length; i++) {
      for (let j = 0; j < portfolio.length; j++) {
        const w1 = portfolio[i].allocation;
        const w2 = portfolio[j].allocation;
        const cov = this.calculateCovariance(
          portfolio[i].asset,
          portfolio[j].asset
        );
        variance += w1 * w2 * cov;
      }
    }

    return Math.sqrt(variance);
  }

  calculateSharpe(portfolio, riskFreeRate = 0.02) {
    const expectedReturn = this.calculateExpectedReturn(portfolio);
    const risk = this.calculateRisk(portfolio);

    return (expectedReturn - riskFreeRate) / risk;
  }

  // Advanced tensor operations (simplified)
  svd(matrix) {
    // Simplified SVD - in production use numeric.js or similar
    // Returns [U, S, V] where matrix = U * S * V^T
    return {
      u: matrix,
      s: [1, 0.5, 0.1], // Example singular values
      v: matrix.map(row => row.map(val => val))
    };
  }

  reshapeTo3DTensor(vector, n) {
    // Reshape flat vector into tensor network structure
    const tensors = [];
    const d = 2; // Binary variables

    for (let i = 0; i < n; i++) {
      const tensor = Array(d).fill().map(() => 
        Array(d).fill().map(() => 
          Math.random()
        )
      );
      tensors.push(tensor);
    }

    return tensors;
  }
}

