## Caching Layer

```javascript
// Add Redis caching for signals
import Redis from 'ioredis';

class CachedOGZPrime extends OGZPrimeMasterBot {
    constructor(config) {
        super(config);
        this.redis = new Redis();
        this.cacheExpiry = 60; // seconds
    }

    async combineSignals(marketData) {
        const key = this.getCacheKey(marketData);

        // Check cache
        const cached = await this.redis.get(key);
        if (cached) {
            return JSON.parse(cached);
        }

        // Generate new signal
        const signal = await super.combineSignals(marketData);

        // Cache it
        await this.redis.setex(key, this.cacheExpiry, JSON.stringify(signal));

        return signal;
    }

    getCacheKey(data) {
        const latest = data[data.length - 1];
        return `signal:${latest.symbol}:${latest.timestamp}`;
    }
}
