/**
 * ========================================================================
 * WEBSOCKET CONFIGURATION - THE FINAL SOLUTION
 * ========================================================================
 * 
 * This is your SINGLE SOURCE OF TRUTH for all WebSocket URLs.
 * Configure once, use everywhere. Never manually change URLs again!
 * 
 * USAGE:
 * const { getWebSocketUrl } = require('./core/WebSocketConfig');
 * const ws = new WebSocket(getWebSocketUrl('data'));
 */

// ========================================================================
// CONFIGURATION - CHANGE THESE ONCE FOR YOUR DEPLOYMENT
// ========================================================================

const CONFIG = {
  // Set to 'production' when deploying to VPS
  environment: process.env.NODE_ENV || 'development',

  // Your production domain (change this to your actual domain)
  productionDomain: process.env.WEBSOCKET_DOMAIN || 'your-domain.com',

  // Use SSL in production?
  useSSL: process.env.USE_SSL === 'true',

  // Port configuration (same for both dev and prod)
  ports: {
    data: process.env.WS_DATA_PORT || 3001,
    gui: process.env.WS_GUI_PORT || 3002,
    control: process.env.WS_CONTROL_PORT || 3003,
    transparency: process.env.WS_TRANSPARENCY_PORT || 3009,
    mover: process.env.WS_MOVER_PORT || 4001,
    stream: process.env.WS_STREAM_PORT || 3005,
    mobile: process.env.WS_MOBILE_PORT || 3004
  },

  // Override URL if needed (for special cases like Docker, reverse proxy, etc.)
  overrideBaseUrl: process.env.WEBSOCKET_BASE_URL || null
};

// ========================================================================
// WEBSOCKET URL GENERATOR - DON'T MODIFY THIS
// ========================================================================

/**
 * Get the WebSocket URL for a specific service
 * @param {string} service - Service name: 'data', 'gui', 'control', etc.
 * @returns {string} Complete WebSocket URL
 */
function getWebSocketUrl(service) {
  // Check if service exists
  if (!CONFIG.ports[service]) {
    throw new Error(`Unknown WebSocket service: ${service}. Valid services: ${Object.keys(CONFIG.ports).join(', ')}`);
  }

  // Use override if provided
  if (CONFIG.overrideBaseUrl) {
    return `${CONFIG.overrideBaseUrl}:${CONFIG.ports[service]}`;
  }

  // Determine base URL based on environment
  let baseUrl;
  if (CONFIG.environment === 'production') {
    const protocol = CONFIG.useSSL ? 'wss' : 'ws';
    baseUrl = `${protocol}://${CONFIG.productionDomain}`;
  } else {
    // Development always uses localhost
    baseUrl = 'ws://localhost';
  }

  // Return complete URL
  return `${baseUrl}:${CONFIG.ports[service]}`;
}

/**
 * Get all WebSocket URLs as an object
 * @returns {Object} Object with all WebSocket URLs
 */
function getAllWebSocketUrls() {
  const urls = {};
  for (const service in CONFIG.ports) {
    urls[service] = getWebSocketUrl(service);
  }
  return urls;
}

/**
 * Get HTTP URL for a service (useful for REST APIs alongside WebSockets)
 * @param {string} service - Service name
 * @returns {string} Complete HTTP URL
 */
function getHttpUrl(service) {
  const wsUrl = getWebSocketUrl(service);
  return wsUrl.replace('ws://', 'http://').replace('wss://', 'https://');
}

/**
 * Check if we're in production mode
 * @returns {boolean} True if production
 */
function isProduction() {
  return CONFIG.environment === 'production';
}

/**
 * Get current configuration (for debugging)
 * @returns {Object} Current configuration
 */
function getConfig() {
  return {
    ...CONFIG,
    currentUrls: getAllWebSocketUrls()
  };
}

// ========================================================================
// SINGLETON WEBSOCKET MANAGER INTEGRATION
// ========================================================================

/**
 * Get or create a WebSocket server using the central configuration
 * @param {string} service - Service name
 * @returns {WebSocketServer} WebSocket server instance
 */
function getWebSocketServer(service) {
  const WebSocketManager = require('./WebSocketManager');
  const port = CONFIG.ports[service];

  if (!port) {
    throw new Error(`Unknown service: ${service}`);
  }

  return WebSocketManager.getServer(port);
}

// ========================================================================
// EXPORTS
// ========================================================================

module.exports = {
  getWebSocketUrl,
  getAllWebSocketUrls,
  getHttpUrl,
  isProduction,
  getConfig,
  getWebSocketServer,

  // Export raw config for special cases
  CONFIG,

  // Convenience exports for common services
  urls: {
    get data() { return getWebSocketUrl('data'); },
    get gui() { return getWebSocketUrl('gui'); },
    get control() { return getWebSocketUrl('control'); },
    get transparency() { return getWebSocketUrl('transparency'); },
    get mover() { return getWebSocketUrl('mover'); },
    get stream() { return getWebSocketUrl('stream'); },
    get mobile() { return getWebSocketUrl('mobile'); }
  }
};

// ========================================================================
// STARTUP LOGGING
// ========================================================================

if (require.main === module) {
  console.log('🔧 WebSocket Configuration:');
  console.log('Environment:', CONFIG.environment);
  console.log('URLs:', getAllWebSocketUrls());
}

