/**
 * CHAINLINK ORACLE INTEGRATION
 */
class ChainlinkOracle {
  constructor() {
    this.provider = null;
    this.priceFeeds = new Map();
    this.cache = new Map();
    this.CACHE_DURATION = 10000; // 10 seconds
  }

  async connect() {
    try {
      this.provider = new ethers.JsonRpcProvider(
        process.env.ETH_RPC_URL || 'https://eth-mainnet.g.alchemy.com/v2/demo'
      );

      // Chainlink price feed addresses (mainnet)
      this.priceFeeds.set('BTC-USD', '0xF4030086522a5bEEa4988F8cA5B36dbC97BeE88c');
      this.priceFeeds.set('ETH-USD', '0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419');
      this.priceFeeds.set('SOL-USD', '0x4ffC43a60e009B551865A93d232E33Fce9f01507');
      this.priceFeeds.set('MATIC-USD', '0x7bAC85A8a13A4BcD8abb3eB7d6b4d632c5a57676');

      console.log('🔗 Chainlink oracles connected');
    } catch (error) {
      console.error('Oracle connection failed:', error);
    }
  }

  async validatePrice(asset, exchangePrice) {
    try {
      const cached = this.cache.get(asset);
      if (cached && Date.now() - cached.timestamp < this.CACHE_DURATION) {
        return this.comparePrice(cached.price, exchangePrice);
      }

      const feedAddress = this.priceFeeds.get(asset);
      if (!feedAddress) return { valid: true, divergence: 0 };

      const aggregatorABI = [
        'function latestRoundData() view returns (uint80, int256, uint256, uint256, uint80)'
      ];

      const aggregator = new ethers.Contract(feedAddress, aggregatorABI, this.provider);
      const roundData = await aggregator.latestRoundData();
      const oraclePrice = Number(roundData[1]) / 1e8;

      this.cache.set(asset, {
        price: oraclePrice,
        timestamp: Date.now()
      });

      return this.comparePrice(oraclePrice, exchangePrice);

    } catch (error) {
      return { valid: true, divergence: 0 };
    }
  }

  comparePrice(oraclePrice, exchangePrice) {
    const divergence = Math.abs(oraclePrice - exchangePrice) / oraclePrice;

    return {
      valid: divergence < 0.05,
      divergence,
      oraclePrice,
      exchangePrice,
      signal: divergence > 0.02 ? 'ARBITRAGE_OPPORTUNITY' : 'NORMAL'
    };
  }
}

