  async getConsensus(analysis) {
    // Convert analysis to tensor
    const features = this.extractFeatures(analysis);
    const input = tf.tensor2d([features]);

    // Get local prediction
    const prediction = await this.model.predict(input).array();
    const localSignal = this.interpretPrediction(prediction[0]);

    // For now, return local prediction as consensus
    // In production, would aggregate from peer network
    return {
      signal: localSignal,
      agreement: Math.max(...prediction[0]),
      peers: this.peers.size
    };
  }

  extractFeatures(analysis) {
    // Convert analysis to feature vector
    return [
      analysis.rsi || 50,
      analysis.macd || 0,
      analysis.trend === 'uptrend' ? 1 : analysis.trend === 'downtrend' ? -1 : 0,
      analysis.volatility || 0.02,
      analysis.confidence || 0.5,
      // Add more features as needed, pad to 20
      ...Array(15).fill(0)
    ];
  }

  interpretPrediction(prediction) {
    const [buy, hold, sell] = prediction;
    if (buy > hold && buy > sell) return 'buy';
    if (sell > hold && sell > buy) return 'sell';
