    // Crash detection
    if (momentum && momentum.rsi < 20 && volume && volume.ratio > 3) {
      regime.type = 'crash';
      regime.characteristics.push('panic_selling');
      regime.tradingMode = 'extreme_caution';
      regime.strength = 1.0;
      regime.confidence = 0.9;
