      "15m": 900000,
      "30m": 1800000,
      "1h": 3600000,
      "2h": 7200000,
      "4h": 14400000,
      "6h": 21600000,
      "8h": 28800000,
      "12h": 43200000,
      "1d": 86400000,
      "3d": 259200000,
      "1w": 604800000,
      "1M": 2629746000 // Average month
    };

    // Configuration with intelligent defaults
    this.config = {
      maxCandles: 2000,           // Increased for more history
      enableCaching: true,        // Performance optimization
